package com.example.rokidgeminisecretary;
import android.app.*;import android.widget.*;import org.json.*;import java.io.*;import java.nio.file.*;
final class MeetingReviewDialog {
 static void show(MainActivity owner,String id){new Thread(()->{try{File folder=MeetingAudioStore.folder(owner,id);JSONObject meta=MeetingAudioStore.meta(folder);JSONArray marks=BookmarkStore.read(folder);StringBuilder result=new StringBuilder();for(String name:new String[]{"summary.gcm","transcript.gcm"}){File file=new File(folder,name);if(file.isFile()&&file.length()<2500000){String text=new String(DeviceSecrets.photos().decrypt(Files.readAllBytes(file.toPath())),"UTF-8");result.append(name.equals("summary.gcm")?"要約\n":"\n文字起こし\n").append(text.length()>100000?text.substring(0,100000)+"\n（表示上限。全文はWebから保存できます）":text);}}String body=result.toString();owner.runOnUiThread(()->{LinearLayout box=new LinearLayout(owner);box.setOrientation(1);box.setPadding(20,12,20,12);TextView status=new TextView(owner);status.setText("しおりの位置は保存された音声の時間です。再生ボタンを押すまで音は出しません。");box.addView(status);MeetingLocalPlayer player=new MeetingLocalPlayer(owner,id,meta.optInt("parts",meta.optJSONArray("parts")==null?0:meta.optJSONArray("parts").length()),status);Button play=new Button(owner);play.setText("最初から再生");play.setOnClickListener(v->player.play(0));box.addView(play);for(int i=0;i<marks.length();i++){JSONObject mark=marks.optJSONObject(i);Button b=new Button(owner);b.setText(mark.optLong("audioMs")/60000+":"+String.format(java.util.Locale.ROOT,"%02d",mark.optLong("audioMs")/1000%60)+" "+mark.optString("label")+" から再生");b.setOnClickListener(v->player.play(mark.optLong("audioMs")));box.addView(b);}Button stop=new Button(owner);stop.setText("再生を停止");stop.setOnClickListener(v->player.stop());box.addView(stop);TextView text=new TextView(owner);text.setTextIsSelectable(true);text.setText(body.isEmpty()?"文字起こし・要約はまだありません":body);box.addView(text);ScrollView scroll=new ScrollView(owner);scroll.addView(box);AlertDialog dialog=new AlertDialog.Builder(owner).setTitle("元の会議記録・しおり").setView(scroll).setPositiveButton("閉じる",null).create();dialog.setOnDismissListener(d->player.stop());dialog.show();});}catch(Exception e){owner.runOnUiThread(()->Toast.makeText(owner,"元の会議記録を開けません",Toast.LENGTH_LONG).show());}},"MeetingReview").start();}
 private MeetingReviewDialog(){}
}
